E2Helper.Descriptions["setHalo"] = [[	Sets a halo around an object:	Usage:	(red, green, blue, alpha, size, passes, additive, throughwall)]]E2Helper.Descriptions["setHaloSize"] ="Sets the size of the halo "E2Helper.Descriptions["setHaloAdd"] ="Sets if the halo will be additive"E2Helper.Descriptions["setHaloColor"] ="Sets the Color of the halo  "E2Helper.Descriptions["setHaloAlpha"] ="Sets the transparency of the halo "E2Helper.Descriptions["setHaloPasses"] ="Sets the pass count for the halo (higher numbers give a thicker look but cause more lag) "E2Helper.Descriptions["setHaloZDepth"] ="Sets if the halo should be rendered through walls"E2Helper.Descriptions["setHaloEnabled"] ="Turns the halo on or off"E2Helper.Descriptions["getHaloSize"] ="Gets the size of the halo "E2Helper.Descriptions["getHaloAdd"] ="Gets if the halo will be additive"E2Helper.Descriptions["getHaloColor"] ="Gets the Color of the halo  "E2Helper.Descriptions["getHaloAlpha"] ="Gets the transparency of the halo "E2Helper.Descriptions["getHaloPasses"] ="Gets the pass count for the halo (higher numbers give a thicker look but cause more lag) "E2Helper.Descriptions["getHaloZDepth"] ="Gets if the halo should be rendered through walls"E2Helper.Descriptions["getHaloEnabled"] ="Is the halo on?"local function Draw()if CLIENT then		hook.Add("PreDrawHalos", "AddHalos", function()		local HaloTables = {}				local OwnerOnly = false				local id = 0				for k, v in pairs (ents.GetAll()) do			if v:GetNWBool("E2HaloGlowEnabled") then				local r = v:GetNWInt("E2HaloGlowR")				local g = v:GetNWInt("E2HaloGlowG")				local b = v:GetNWInt("E2HaloGlowB")				local a = v:GetNWInt("E2HaloGlowA")				local size = v:GetNWInt("E2HaloGlowSize")				local passes = v:GetNWInt("E2HaloGlowPasses")				local additive = v:GetNWInt("E2HaloGlowAdditive")				local twalls = v:GetNWBool("E2HaloGlowThroughWalls")				local twallsint = 0				if twalls then					twallsint = 1				end				local datastr = r .. "-" .. g .. "-" .. b .. "-" .. a .. "-" .. size .. "-" .. passes .. "-" .. additive .. "-" .. twallsint				if !HaloTables[datastr] then					HaloTables[datastr] = {}					if !table.HasValue(HaloTables[datastr], v) then						table.insert(HaloTables[datastr], v)					end				else					if !table.HasValue(HaloTables[datastr], v) then						table.insert(HaloTables[datastr], v)					end				end			end		end		for k, v in pairs (HaloTables) do			local dataparse = string.Explode("-", k)			local parsed_r = tonumber(dataparse[1])			local parsed_g = tonumber(dataparse[2])			local parsed_b = tonumber(dataparse[3])			local parsed_a = tonumber(dataparse[4])			local parsed_size = tonumber(dataparse[5])			local parsed_passes = tonumber(dataparse[6])			local parsed_additive = (tonumber(dataparse[7]) == 1)			local parsed_twalls = (tonumber(dataparse[8]) == 1)				halo.Add(v, Color(parsed_r, parsed_g, parsed_b, parsed_a), parsed_size, parsed_size, parsed_passes, parsed_additive, parsed_twalls)				--print("showing halo to everyone")					end		--print("I loaded!")	end)endendhook.Add("HUDPaint","halo.draw",Draw)--print("I loaded!")